{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "protocol",
      "alternatives": [
        "(df['proto'] == 'tcp') | ((df['swin'] == 0) & (df['dwin'] == 0) & (df['stcpb'] == 0) & (df['dtcpb'] == 0) & (df['tcprtt'] == 0) & (df['synack'] == 0) & (df['ackdat'] == 0) & (df['sloss'] == 0) & (df['dloss'] == 0))"
      ],
      "features": ["proto", "swin", "dwin", "stcpb", "dtcpb", "tcprtt", "synack", "ackdat", "sloss", "dloss"],
      "rationale": "TCP-specific fields should be zero for non-TCP protocols."
    },
    {
      "id": "R2",
      "category": "protocol",
      "alternatives": [
        "(df['service'] == 'http') | ((df['trans_depth'] == 0) & (df['response_body_len'] == 0))"
      ],
      "features": ["service", "trans_depth", "response_body_len"],
      "rationale": "HTTP-specific fields should be zero for non-HTTP services."
    },
    {
      "id": "R3",
      "category": "protocol",
      "alternatives": [
        "(df['service'] == 'ftp') | (df['is_ftp_login'] == 0)"
      ],
      "features": ["service", "is_ftp_login"],
      "rationale": "FTP login flag should be zero for non-FTP services."
    },
    {
      "id": "R4",
      "category": "protocol",
      "alternatives": [
        "~(df['state'].isin(['ACC', 'CLO', 'CON', 'FIN', 'RST'])) | (df['proto'] == 'tcp')",
        "~(df['state'].isin(['ACC', 'CLO', 'CON', 'FIN', 'RST', 'REQ'])) | (df['proto'] == 'tcp')"
      ],
      "features": ["state", "proto"],
      "rationale": "TCP-specific states imply the protocol is TCP."
    },
    {
      "id": "R5",
      "category": "protocol",
      "alternatives": [
        "~(df['state'].isin(['ECO', 'ECR'])) | (df['proto'] == 'icmp')"
      ],
      "features": ["state", "proto"],
      "rationale": "ICMP-specific states imply the protocol is ICMP."
    },
    {
      "id": "R6",
      "category": "protocol",
      "alternatives": [
        "~(df['service'].isin(['http', 'ftp', 'ssh', 'smtp', 'ftp-data', 'irc'])) | (df['proto'] == 'tcp')"
      ],
      "features": ["service", "proto"],
      "rationale": "Services known to run over TCP imply the protocol is TCP."
    },
    {
      "id": "R7",
      "category": "protocol",
      "alternatives": [
        "(df['service'] != 'dns') | (df['proto'].isin(['udp', 'tcp']))"
      ],
      "features": ["service", "proto"],
      "rationale": "DNS service can only use UDP or TCP."
    }
  ]
}
